import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 미승인 근태 신청이 있으면 마감을 막는다 (정책)
const BLOCK_ON_UNAPPROVED = true;

type Db = {
  query(sql: string, params?: Record<string, unknown>): Promise<any[]>;
  execute(sql: string, params?: Record<string, unknown>): Promise<number>;
};

// 가정: 월 마감의 마감 대상 일자는 해당 월 1일
const MONTH_START = `CAST(date_trunc('month', CAST(:closingDate AS date)) AS date)`;
const MONTH_END = `CAST(date_trunc('month', CAST(:closingDate AS date)) + interval '1 month' AS date)`;

function readTarget(src: Record<string, unknown>) {
  const unit = src['closingUnit'];
  const date = src['closingDate'];
  if (unit !== '일' && unit !== '월') {
    throw new ApiError(400, 'VALIDATION_FAILED', '마감 단위는 일 또는 월이어야 합니다.');
  }
  if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '마감 대상 일자를 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return { closingUnit: unit as string, closingDate: date };
}

function keyDate(unit: string): string {
  return unit === '월' ? MONTH_START : 'CAST(:closingDate AS date)';
}

function commuteCond(unit: string, col: string): string {
  if (unit === '월') {
    return col + ' >= ' + MONTH_START + ' AND ' + col + ' < ' + MONTH_END;
  }
  return col + ' = CAST(:closingDate AS date)';
}

function requestCond(unit: string): string {
  if (unit === '월') {
    return 'start_date < ' + MONTH_END + ' AND end_date >= ' + MONTH_START;
  }
  return 'start_date <= CAST(:closingDate AS date) AND end_date >= CAST(:closingDate AS date)';
}

async function assertNotClosed(db: Db, closingUnit: string, closingDate: string) {
  const rows = await db.query(
    'SELECT attendance_closing_id FROM attendance_closing WHERE closing_unit = :closingUnit AND closing_date = ' +
      keyDate(closingUnit) +
      " AND status = '마감'",
    { closingUnit, closingDate },
  );
  if (rows.length > 0) {
    throw new ApiError(409, 'ATTENDANCE_ALREADY_CLOSED', '이미 마감된 기간입니다.');
  }
}

async function countUnapproved(db: Db, closingUnit: string, closingDate: string): Promise<number> {
  const rows = await db.query(
    "SELECT COUNT(*) AS n FROM attendance_request WHERE approval_status = '신청' AND " + requestCond(closingUnit),
    { closingDate },
  );
  return Number(rows[0].n);
}

async function countRecords(db: Db, closingUnit: string, closingDate: string): Promise<number> {
  const rows = await db.query(
    'SELECT COUNT(*) AS n FROM commute_record WHERE ' + commuteCond(closingUnit, 'work_date'),
    { closingDate },
  );
  return Number(rows[0].n);
}

@Controller('api/v1')
export class FnSfr01807Controller {
  @Get('/attendance-closings/preview')
  async previewAttendanceClosing(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const { closingUnit, closingDate } = readTarget(q);
    return transaction(async (db: Db) => {
      await assertNotClosed(db, closingUnit, closingDate);
      const unapprovedCount = await countUnapproved(db, closingUnit, closingDate);
      const recordCount = await countRecords(db, closingUnit, closingDate);
      return { unapprovedCount, recordCount };
    });
  }

  @Post('/attendance-closings')
  @HttpCode(200)
  async createAttendanceClosing(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const { closingUnit, closingDate } = readTarget(data);
    return transaction(async (db: Db) => {
      const existing = await db.query(
        'SELECT attendance_closing_id AS "attendanceClosingId", status FROM attendance_closing ' +
          'WHERE closing_unit = :closingUnit AND closing_date = ' +
          keyDate(closingUnit) +
          ' FOR UPDATE',
        { closingUnit, closingDate },
      );
      if (existing.length > 0 && existing[0].status === '마감') {
        throw new ApiError(409, 'ATTENDANCE_ALREADY_CLOSED', '이미 마감된 기간입니다.');
      }
      if (BLOCK_ON_UNAPPROVED) {
        const unapproved = await countUnapproved(db, closingUnit, closingDate);
        if (unapproved > 0) {
          throw new ApiError(422, 'UNAPPROVED_REQUEST_EXISTS', '미승인 근태 신청이 있어 마감할 수 없습니다.');
        }
      }
      let rows: any[];
      if (existing.length > 0) {
        // 마감 취소된 기간을 다시 마감한다 (단위·일자 유일 제약)
        rows = await db.query(
          "UPDATE attendance_closing SET status = '마감', closed_at = now(), cancelled_at = NULL, updated_at = now() " +
            'WHERE attendance_closing_id = :id ' +
            'RETURNING attendance_closing_id AS "attendanceClosingId", status, closed_at AS "closedAt"',
          { id: existing[0].attendanceClosingId },
        );
      } else {
        rows = await db.query(
          'INSERT INTO attendance_closing (closing_unit, closing_date, status, closed_at, created_at, updated_at) ' +
            "VALUES (:closingUnit, " +
            keyDate(closingUnit) +
            ", '마감', now(), now(), now()) " +
            'RETURNING attendance_closing_id AS "attendanceClosingId", status, closed_at AS "closedAt"',
          { closingUnit, closingDate },
        );
      }
      await db.execute(
        'UPDATE commute_record SET is_closed = true, updated_at = now() WHERE ' + commuteCond(closingUnit, 'work_date'),
        { closingDate },
      );
      return rows[0];
    });
  }

  @Post('/attendance-closings/:attendanceClosingId/cancel')
  @HttpCode(200)
  async cancelAttendanceClosing(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    checks.inputOf(req.body);
    const id = req.params['attendanceClosingId'];
    if (typeof id !== 'string' || !/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 마감 ID가 올바르지 않습니다.');
    }
    return transaction(async (db: Db) => {
      const found = await db.query(
        'SELECT closing_unit AS "closingUnit", CAST(closing_date AS text) AS "closingDate", status ' +
          'FROM attendance_closing WHERE attendance_closing_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_CLOSING_NOT_FOUND', '마감 건을 찾을 수 없습니다.');
      }
      const row = found[0];
      if (row.status !== '마감') {
        throw new ApiError(409, 'ATTENDANCE_NOT_CLOSED', '마감 상태가 아닙니다.');
      }
      const rows = await db.query(
        "UPDATE attendance_closing SET status = '마감 취소', cancelled_at = now(), updated_at = now() " +
          'WHERE attendance_closing_id = CAST(:id AS bigint) ' +
          'RETURNING attendance_closing_id AS "attendanceClosingId", status, cancelled_at AS "cancelledAt"',
        { id },
      );
      // 다른 유효한 마감(일·월)이 같은 기록을 덮고 있으면 마감 상태를 유지한다
      await db.execute(
        'UPDATE commute_record SET is_closed = false, updated_at = now() WHERE ' +
          commuteCond(row.closingUnit, 'work_date') +
          " AND NOT EXISTS (SELECT 1 FROM attendance_closing c WHERE c.status = '마감' AND (" +
          "(c.closing_unit = '일' AND c.closing_date = commute_record.work_date) OR " +
          "(c.closing_unit = '월' AND date_trunc('month', c.closing_date) = date_trunc('month', commute_record.work_date))))",
        { closingDate: row.closingDate },
      );
      return rows[0];
    });
  }
}

