import { useState } from 'react';
import {
  call,
  Badge,
  DateText,
  Band,
  DataTable,
  Drawer,
  Form,
  Field,
  Select,
  DateInput,
  Tiles,
  Num,
} from '../kit';
import type { PageProps, Row } from '../kit';

type Closing = {
  attendanceClosingId: number;
  closingUnit: string;
  closingDate: string;
  status: string;
  closedAt?: string;
  cancelledAt?: string;
};

export default function FnSfr01807Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 결과를 목록으로 보인다
  const [rows, setRows] = useState<Closing[]>([]);
  const [mode, setMode] = useState<'none' | 'close' | 'cancel'>('none');
  const [target, setTarget] = useState<Closing | undefined>();
  const [unit, setUnit] = useState('일');
  const [date, setDate] = useState('');
  const [preview, setPreview] = useState<Row | undefined>();

  function closePanel() {
    setMode('none');
    setTarget(undefined);
    setPreview(undefined);
    setUnit('일');
    setDate('');
  }

  function check() {
    if (!date) {
      throw new Error('마감 대상 일자를 입력해 주세요.');
    }
  }

  async function loadPreview() {
    check();
    const res = await call('GET', '/attendance-closings/preview', role, undefined, {
      closingUnit: unit,
      closingDate: date,
    });
    setPreview(res);
  }

  async function runClose() {
    check();
    const res = await call<Row>('POST', '/attendance-closings', role, {
      closingUnit: unit,
      closingDate: date,
    });
    const added: Closing = {
      attendanceClosingId: Number(res.attendanceClosingId),
      closingUnit: unit,
      closingDate: date,
      status: String(res.status),
      closedAt: String(res.closedAt),
    };
    setRows([added, ...rows.filter((r) => r.attendanceClosingId !== added.attendanceClosingId)]);
    notify('근태를 마감했습니다.');
    closePanel();
  }

  async function runCancel() {
    if (!target) {
      return;
    }
    const res = await call<Row>(
      'POST',
      '/attendance-closings/' + target.attendanceClosingId + '/cancel',
      role,
      {},
    );
    setRows(
      rows.map((r) =>
        r.attendanceClosingId === target.attendanceClosingId
          ? { ...r, status: String(res.status), cancelledAt: String(res.cancelledAt) }
          : r,
      ),
    );
    notify('근태 마감을 취소했습니다.');
    closePanel();
  }

  return (
    <div>
      <h1>근태 확정 관리</h1>
      <Band total={rows.length}>
        <button
          onClick={() => {
            closePanel();
            setMode('close');
          }}
        >
          근태 마감
        </button>
      </Band>
      <DataTable<Closing>
        rows={rows}
        empty='아직 처리한 마감 내역이 없습니다. 근태 마감 버튼으로 마감 기간을 선택해 시작하세요.'
        columns={[
          { key: 'closingUnit', label: '마감 단위' },
          { key: 'closingDate', label: '마감 대상 일자', render: (r) => <DateText value={r.closingDate} /> },
          { key: 'status', label: '마감 상태', render: (r) => <Badge value={r.status} /> },
          { key: 'closedAt', label: '마감 일시', render: (r) => <DateText value={r.closedAt} time /> },
          {
            key: 'action',
            label: '처리',
            render: (r) =>
              r.status === '마감' ? (
                <button
                  className='ghost'
                  onClick={(e) => {
                    e.stopPropagation();
                    setTarget(r);
                    setMode('cancel');
                  }}
                >
                  마감 취소
                </button>
              ) : null,
          },
        ]}
      />
      {mode === 'close' && (
        <Drawer title='근태 마감' onClose={closePanel}>
          {!preview ? (
            <Form submit='집계 보기' onSubmit={loadPreview}>
              <Field label='마감 단위' required>
                <Select
                  value={unit}
                  onChange={setUnit}
                  options={[
                    ['일', '일'],
                    ['월', '월'],
                  ]}
                />
              </Field>
              <Field label='마감 대상 일자' required hint='월 마감은 해당 월의 날짜를 고르면 됩니다.'>
                <DateInput value={date} onChange={setDate} />
              </Field>
            </Form>
          ) : (
            <div>
              <Tiles
                items={[
                  ['미승인 근태 신청 건수', <Num value={preview.unapprovedCount} />],
                  ['집계 대상 출퇴근 기록 건수', <Num value={preview.recordCount} />],
                ]}
              />
              <Form
                submit='마감 실행'
                note='마감한 기간의 데이터는 마감을 취소하기 전에는 수정할 수 없습니다. 미승인 근태 신청이 있으면 마감되지 않습니다.'
                onSubmit={runClose}
              >
                <button type='button' className='ghost' onClick={() => setPreview(undefined)}>
                  기간 다시 선택
                </button>
              </Form>
            </div>
          )}
        </Drawer>
      )}
      {mode === 'cancel' && target && (
        <Drawer title='근태 마감 취소' onClose={closePanel}>
          <Form
            submit='마감 취소'
            danger
            note={'마감 취소하면 해당 기간의 출퇴근 기록을 다시 수정할 수 있습니다. 대상: ' + target.closingDate + ' (' + target.closingUnit + ' 마감)'}
            onSubmit={runCancel}
          />
        </Drawer>
      )}
    </div>
  );
}
